<?php
declare(strict_types=1); namespace Wms;
final class InventoryService extends Service {
 public function cells(string$a,array$p,array$u):array{if($a==='list'){[$page,$size,$offset]=Util::page($p);$q='%'.Util::text($p['search']??'').'%';$total=(int)$this->db->one("SELECT COUNT(*)n FROM cells WHERE deleted_at IS NULL AND (?='%%' OR name LIKE ?)",[$q,$q])['n'];$rows=$this->db->all("SELECT c.*,COALESCE(SUM(s.quantity),0)total FROM cells c LEFT JOIN stock s ON s.cell_id=c.id WHERE c.deleted_at IS NULL AND (?='%%' OR c.name LIKE ?) GROUP BY c.id ORDER BY c.name LIMIT ? OFFSET ?",[$q,$q,$size,$offset]);return['items'=>array_map(fn($x)=>$this->camel($x),$rows),'page'=>$page,'pageSize'=>$size,'total'=>$total,'pages'=>(int)ceil($total/$size)];}if($a==='get'){$c=$this->one('SELECT * FROM cells WHERE id=? AND deleted_at IS NULL',[$p['id']??''],'Ячейка не найдена');$items=$this->db->all('SELECT i.name,s.quantity,p.number prn_number,d.number delivery_number,s.updated_at FROM stock s JOIN prn_items i ON i.id=s.prn_item_id JOIN prns p ON p.id=i.prn_id JOIN deliveries d ON d.id=p.delivery_id WHERE s.cell_id=? AND s.quantity>0 ORDER BY i.name',[$c['id']]);return['cell'=>$this->camel($c),'items'=>array_map(fn($x)=>$this->camel($x),$items),'total'=>array_sum(array_column($items,'quantity'))];}if($u['role']!=='admin')throw new ApiException('FORBIDDEN','Недостаточно прав',403);if($a==='create'){$name=strtoupper(Util::text($p['name']??''));if(!$name)throw new ApiException('VALIDATION','Укажите название ячейки');if($this->db->one('SELECT id FROM cells WHERE name=?',[$name]))throw new ApiException('DUPLICATE','Такая ячейка уже существует');$id=Util::uuid();$this->db->exec('INSERT INTO cells(id,name,description,created_at,created_by) VALUES(?,?,?,?,?)',[$id,$name,Util::text($p['description']??''),Util::now(),$u['id']]);$this->audit->log($u,'CREATE','cell',$id,[],['name'=>$name]);return['id'=>$id,'name'=>$name,'version'=>1];}$cell=$this->one('SELECT * FROM cells WHERE id=? AND deleted_at IS NULL',[$p['id']??''],'Ячейка не найдена');if($a==='update'){$name=strtoupper(Util::text($p['name']??''));if(!$name)throw new ApiException('VALIDATION','Укажите название ячейки');if($this->db->one('SELECT id FROM cells WHERE name=? AND id<>?',[$name,$cell['id']]))throw new ApiException('DUPLICATE','Такая ячейка уже существует');$this->conflict($this->db->exec('UPDATE cells SET name=?,description=?,version=version+1 WHERE id=? AND version=?',[$name,Util::text($p['description']??''),$cell['id'],(int)$p['version']]));$this->audit->log($u,'UPDATE','cell',$cell['id'],$cell,$p);return[];}if($a==='delete'){if($this->db->one('SELECT id FROM stock WHERE cell_id=? AND quantity>0 LIMIT 1',[$cell['id']]))throw new ApiException('DEPENDENCY','Невозможно удалить ячейку: на ней находится товар.');$this->conflict($this->db->exec('UPDATE cells SET deleted_at=?,version=version+1 WHERE id=? AND version=?',[Util::now(),$cell['id'],(int)$p['version']]));$this->audit->log($u,'DELETE','cell',$cell['id'],$cell,[]);return[];}throw new ApiException('ROUTE','Неизвестное действие');}
 public function place(string$a,array$p,array$u):array{return$this->db->transaction(function()use($a,$p,$u){$cell=$this->one('SELECT * FROM cells WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$p['cellId']??''],'Ячейка не найдена');if($a==='pallet'){$pal=$this->one('SELECT * FROM pallets WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$p['palletId']??''],'Палета не найдена');if($pal['placed_at'])throw new ApiException('VALIDATION','Палета уже размещена');if((int)$pal['version']!==(int)$p['version'])throw new ApiException('CONFLICT','Данные были изменены другим пользователем. Информация обновлена. Повторите действие.',409);$lines=$this->db->all('SELECT * FROM pallet_items WHERE pallet_id=? AND deleted_at IS NULL',[$pal['id']]);if(!$lines)throw new ApiException('VALIDATION','Палета пуста');foreach($lines as$x)$this->add($cell['id'],$x['prn_item_id'],(int)$x['quantity'],$pal['prn_id'],$pal['id'],$u['id']);$this->db->exec("UPDATE pallets SET status='Размещена',cell_id=?,placed_at=?,version=version+1 WHERE id=?",[$cell['id'],Util::now(),$pal['id']]);$this->audit->log($u,'PLACE_PALLET','prn',$pal['prn_id'],[],['pallet'=>$pal['number'],'cell'=>$cell['name']]);return[];}if($a==='item'){$i=$this->one('SELECT * FROM prn_items WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$p['prnItemId']??''],'Позиция не найдена');if((int)$i['version']!==(int)$p['version'])throw new ApiException('CONFLICT','Данные были изменены другим пользователем. Информация обновлена. Повторите действие.',409);$q=Util::qty($p['quantity']??0);$palleted=(int)$this->db->one('SELECT COALESCE(SUM(quantity),0)n FROM pallet_items WHERE prn_item_id=? AND deleted_at IS NULL',[$i['id']])['n'];$placed=(int)$this->db->one('SELECT COALESCE(SUM(quantity),0)n FROM placements WHERE prn_item_id=?',[$i['id']])['n'];if($q>(int)$i['received']-$palleted||$q>(int)$i['received']-$placed)throw new ApiException('VALIDATION','Недостаточно неупакованного товара для размещения');$this->add($cell['id'],$i['id'],$q,$i['prn_id'],null,$u['id']);$this->audit->log($u,'PLACE_ITEM','prn',$i['prn_id'],[],['item'=>$i['name'],'quantity'=>$q,'cell'=>$cell['name']]);return[];}throw new ApiException('ROUTE','Неизвестное действие');});}
 private function add(string$c,string$i,int$q,string$p,?string$pal,string$u):void{$this->db->exec('INSERT INTO stock(id,cell_id,prn_item_id,quantity,updated_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity),updated_at=VALUES(updated_at),version=version+1',[Util::uuid(),$c,$i,$q,Util::now()]);$this->db->exec('INSERT INTO placements(id,prn_id,prn_item_id,pallet_id,cell_id,quantity,created_at,created_by) VALUES(?,?,?,?,?,?,?,?)',[Util::uuid(),$p,$i,$pal,$c,$q,Util::now(),$u]);}
 public function search(array$p):array{$q='%'.Util::text($p['query']??'').'%';if(mb_strlen(Util::text($p['query']??''))<2)return[];$rows=$this->db->all('SELECT i.name,c.name cell_name,SUM(s.quantity)quantity FROM stock s JOIN prn_items i ON i.id=s.prn_item_id JOIN cells c ON c.id=s.cell_id WHERE i.name LIKE ? AND s.quantity>0 GROUP BY i.name,c.name ORDER BY i.name,c.name',[$q]);$out=[];foreach($rows as$r){$k=mb_strtolower($r['name']);$out[$k]??=['name'=>$r['name'],'total'=>0,'cells'=>[]];$out[$k]['total']+=(int)$r['quantity'];$out[$k]['cells'][]=['name'=>$r['cell_name'],'quantity'=>(int)$r['quantity']];}return array_values($out);}
 public function dashboard():array{return['expectedVehicles'=>(int)$this->db->one("SELECT COUNT(*)n FROM vehicles WHERE deleted_at IS NULL AND status='Грузится в Киеве'")['n'],'unloadedToday'=>(int)$this->db->one('SELECT COUNT(*)n FROM vehicles WHERE deleted_at IS NULL AND DATE(unloaded_at)=CURDATE()')['n'],'reception'=>(int)$this->db->one('SELECT COUNT(*)n FROM prns WHERE deleted_at IS NULL AND reception_started_at IS NOT NULL AND ready_at IS NULL')['n'],'awaitingPlacement'=>(int)$this->db->one('SELECT COUNT(*)n FROM prns WHERE deleted_at IS NULL AND ready_at IS NOT NULL AND closed_at IS NULL')['n'],'unfinished'=>(int)$this->db->one('SELECT COUNT(*)n FROM prns WHERE deleted_at IS NULL AND closed_at IS NULL')['n']];}
}
